"""Fourteen project-specific deep study pages with real result tables and row inspection."""
import json,html,sys,hashlib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'scripts'))
from academic_project_style import CSS,icon
E=html.escape
EXTRA='''pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.6 ui-monospace,monospace;background:#fafafa;border:1px solid #ddd;padding:15px;max-height:520px;overflow:auto}summary{cursor:pointer}details{padding:15px 0;border-bottom:1px solid #ddd}.controls{display:flex;gap:14px;flex-wrap:wrap;margin:20px 0}label{font-size:14px}input,select{display:block;border:1px solid #aaa;border-radius:0;background:white;padding:8px;max-width:100%}button{border:1px solid #999;background:white;padding:8px 15px}button:disabled{opacity:.4}.records td{white-space:normal;max-width:200px;overflow-wrap:anywhere}.records tr{cursor:pointer}.records tr:hover{background:#f7f7f7}.chart{width:100%;max-height:270px}.chart text{font-family:Arial,sans-serif;fill:#666;font-size:12px}blockquote{border-left:3px solid #777;padding-left:20px;margin:22px 0}.publication-title{word-break:normal}@media(max-width:600px){.publication-title{font-size:32px}.controls{display:grid;grid-template-columns:1fr 1fr}label:last-child{grid-column:1/-1}}'''
def value(v):
 if isinstance(v,float):return f'{v:.5g}'
 return '—' if v is None else str(v)
def plot(metrics):
 keys=[k for k in ['accuracy','test_chosen_top1','new_accuracy','coverage','mean_nmse','mae_ms','f1','all_rmse','weighted_error','total_variation'] if any(isinstance(r.get(k),(float,int)) for r in metrics)]
 if not keys:return ''
 key=keys[0];values=[(i,r[key]) for i,r in enumerate(metrics) if isinstance(r.get(key),(float,int))];maxv=max(v for i,v in values) or 1;w=860;h=230;axis='<line x1="45" x2="845" y1="195" y2="195" stroke="#888"/><line x1="45" x2="45" y1="20" y2="195" stroke="#888"/>'
 points=' '.join(f'{45+(i/(max(len(metrics)-1,1)))*790:.2f},{195-(v/maxv)*160:.2f}' for i,v in values)
 return '<figure><svg class="chart" viewBox="0 0 860 230" role="img" aria-label="'+E(key)+'全部条件按原顺序绘制">'+axis+'<polyline points="'+points+'" fill="none" stroke="#456779" stroke-width="1.7"/>'+''.join(f'<circle cx="{45+i/max(len(metrics)-1,1)*790:.2f}" cy="{195-v/maxv*160:.2f}" r="2.5" fill="#456779"/>' for i,v in values)+'<text x="45" y="220">条件索引 0</text><text x="760" y="220">'+str(len(metrics)-1)+'</text><text x="5" y="195">0</text><text x="4" y="30">'+E(f'{maxv:.3g}')+'</text></svg><figcaption class="caption">'+E(key)+'，全部条件按原始结果顺序。索引不是连续物理量，折线只辅助读表，不代表插值或趋势拟合。</figcaption></figure>'
def build():
 index=json.loads((ROOT/'docs/investigations-index.json').read_text());cards=[]
 for item in index:
  folder=item['project'];p=ROOT/'projects'/folder;d=json.loads((p/'artifacts/investigation/results.json').read_text());analysis=json.loads((p/'artifacts/investigation/analysis.json').read_text());fields=list(dict.fromkeys(k for r in d['metrics'] for k in r));fields=fields[:14]
  table='<div class="table-scroll"><table class="paper-table"><thead><tr>'+''.join('<th>'+E(k)+'</th>' for k in fields)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+E(value(r.get(k)))+'</td>' for k in fields)+'</tr>' for r in d['metrics'])+'</tbody></table></div>'
  body='<nav class="project-top"><a href="../../index.html#experiments">← Portfolio</a><a href="project.html">Project overview</a></nav><header class="publication-header"><h1 class="publication-title">'+E(d['title'])+'</h1><h2 class="publication-subtitle">Deep Investigation</h2><div class="publication-authors">Yu Yue（于跃）</div><p class="publication-note">AI 辅助实现 · 真实本地实验 / 冻结再分析按协议区分 · 非论文或生产项目</p><div class="publication-links">'+''.join('<a class="resource" href="'+url+'">'+icon(k)+name+'</a>' for k,name,url in [('code','Code','https://github.com/LlewynLune/ai-portfolio/tree/main/projects/investigations'),('report','Report','https://github.com/LlewynLune/ai-portfolio/blob/main/projects/'+folder+'/artifacts/investigation/REPORT.md'),('data','Evidence','#records'),('report','Earlier study','depth-demo.html')])+'</div></header><main>'
  body+='<section class="project-section narrow"><h2>Research Question</h2><p>'+E(d['question'])+'</p><h3>What was actually done</h3><pre>'+E(json.dumps(d['protocol'],ensure_ascii=False,indent=2))+'</pre><p class="caption">协议在本项目首次实验运行前写入。条件扫描、不同行的重复变体和不同项目记录定义不同，不能将记录总量视为独立样本规模。</p></section>'
  body+='<section class="project-section"><h2>Experimental Results</h2>'+plot(d['metrics'])+table+'<p class="caption">直接读取artifacts/investigation/results.json，全部条件不按最好结果筛选。'+str(len(d['records']))+'条记录可能是相关扰动、抽样计数、历史预测或运行级摘要；不是统一样本定义。</p></section>'
  baseline=p/'artifacts/investigation/rule-baseline.json'
  if baseline.exists():
   b=json.loads(baseline.read_text());body+='<section class="project-section narrow"><h2>Deterministic Rule Baseline</h2><p>已知有限查找规则的传统解析器通过 '+str(b['correct'])+'/'+str(b['n'])+'。规则基线直接解析合成语法与已知shift，无训练或模型生成。它是适当强基线，表明模型高分不是必要性证明；相关重复条件仍不独立。</p></section>'
  body+='<section class="project-section narrow"><h2>Findings &amp; Failure Analysis</h2>'+''.join('<p>'+E(t)+'</p>' for t in analysis['observations'])+'<h3>Limitations</h3>'+''.join('<p>'+E(t)+'</p>' for t in d['findings'])+'</section>'
  rows=d['records'];payload=json.dumps(rows,ensure_ascii=False,separators=(',',':')).replace('</',r'<\/')
  body+='''<section class="project-section" id="records"><h2>Evidence Inspector</h2><p>逐条真实结果，可按条件/策略检索并导出；页面不重新训练或运行完整LLM。</p><div class="controls"><label>关键词<input id="query" placeholder="condition / model / seed"></label><label>页大小<select id="size"><option>20</option><option>50</option><option>100</option></select></label><label>分页<button id="prev">上一页</button> <button id="next">下一页</button></label></div><p id="count" class="caption" aria-live="polite"></p><div class="table-scroll"><table class="paper-table records"><thead id="heads"></thead><tbody id="rows"></tbody></table></div><h3>Selected record</h3><pre id="selected"></pre><button id="export">导出所选 JSON</button></section>'''
  body+='<section class="project-section narrow"><h2>Next Uncompleted Work</h2><p>'+E(analysis['next_step'])+'</p><p class="caption">这一节是尚未完成的下一阶段，不是本轮成果。</p><details><summary>来源与环境完整性</summary><pre>'+E(json.dumps({'environment':d['environment'],'source_sha256':d['source_sha256'],'result_sha256':analysis['results_sha256']},ensure_ascii=False,indent=2))+'</pre></details></section></main><footer class="project-footer">个人实验 · AI 辅助实现 · 不增加业务履历、生产成绩或原创论文<br><a href="../../project-investigations.html">全部项目深化</a></footer>'
  js='''<script>const DATA='''+payload+''';const $=id=>document.getElementById(id),esc=x=>String(x??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let page=0,filtered=DATA,chosen=null;
 const keys=[...new Set(DATA.flatMap(r=>Object.keys(r).filter(k=>r[k]===null||['string','number','boolean'].includes(typeof r[k]))))].slice(0,9);
 $('heads').innerHTML='<tr>'+keys.map(k=>'<th>'+esc(k)+'</th>').join('')+'</tr>';
 function draw(){const size=+$('size').value,total=Math.max(1,Math.ceil(filtered.length/size));page=Math.min(Math.max(page,0),total-1);const visible=filtered.slice(page*size,(page+1)*size);$('rows').innerHTML=visible.map((r,i)=>'<tr data-index="'+i+'" tabindex="0">'+keys.map(k=>'<td>'+esc(typeof r[k]==='number'&&!Number.isInteger(r[k])?r[k].toPrecision(5):r[k])+'</td>').join('')+'</tr>').join('');$('count').textContent=filtered.length+'条记录 · 第'+(page+1)+'/'+total+'页 · 每页'+size;$('prev').disabled=page===0;$('next').disabled=page>=total-1;
 function pick(i){chosen=visible[i];$('selected').textContent=chosen?JSON.stringify(chosen,null,2):'无匹配记录。'}document.querySelectorAll('[data-index]').forEach(el=>{el.onclick=()=>pick(+el.dataset.index);el.onkeydown=e=>{if(e.key==='Enter')pick(+el.dataset.index)}});pick(0)}
 $('query').oninput=()=>{const q=$('query').value.toLowerCase();filtered=q?DATA.filter(r=>keys.some(k=>String(r[k]).toLowerCase().includes(q))):DATA;page=0;draw()};$('size').onchange=()=>{page=0;draw()};$('prev').onclick=()=>{page--;draw()};$('next').onclick=()=>{page++;draw()};$('export').onclick=()=>{if(!chosen)return;const u=URL.createObjectURL(new Blob([JSON.stringify(chosen,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='investigation-record.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};draw();</script>'''
  (p/'deep-study.html').write_text('<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+E(d['title'])+'</title><style>'+CSS+EXTRA+'</style></head><body>'+body+js+'</body></html>')
  cards.append('<article><h2><a href="projects/'+folder+'/deep-study.html">'+E(d['title'])+'</a></h2><p>'+E(d['question'])+'</p><p>'+E(analysis['observations'][0])+'</p><p class="caption">'+str(len(d['records']))+'条记录 · '+str(len(d['metrics']))+'完整条件 · <a href="projects/'+folder+'/deep-study.html#records">逐条证据 →</a></p></article>')
 business=[]
 for case in json.loads((ROOT/'profile/resume.json').read_text())['cases']:business.append('<li><a href="business-cases/'+case['id']+'/case.html">'+E(case['title'])+'</a> · 产品取舍、建议指标、验收场景与证据缺口；不添加既往成绩。</li>')
 home='<nav class="project-top"><a href="index.html#experiments">← Portfolio</a></nav><header class="publication-header"><h1 class="publication-title">Project Investigations</h1><h2 class="publication-subtitle">14 Research Studies · 4 Product Cases</h2><p>Yu Yue（于跃） · AI 辅助实现 · 全条件实验与失败分析</p></header><main class="project-section"><p>不新增项目数量，不以统一卡片或参数扫面替代研究深度。本轮每项围绕一个不同问题实跑实验或重新分析冻结证据，明确方法、强基线、限制和未完成项。</p>'+''.join(cards)+'<h2>Product Case Analysis</h2><ul>'+''.join(business)+'</ul><p class="caption">真实业务案例仅基于已确认简历解释产品判断。新验收建议不是原项目已做成果。</p></main>'
 (ROOT/'project-investigations.html').write_text('<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>于跃｜逐项目深化</title><style>'+CSS+'article{border-bottom:1px solid #ddd;padding:25px 0}article h2{text-align:left!important;font-size:23px!important}li{margin:16px 0}</style></head><body>'+home+'</body></html>')
 print('built',len(index),'deep study pages and index')
if __name__=='__main__':build()
